#include "plugin.h"

void DXNotebook::help(){
 ImGui::SetNextWindowSize({720,620},ImGuiCond_FirstUseEver);
 if(!ImGui::BeginPopupModal("Decoder help",nullptr,ImGuiWindowFlags_None))return;
 popup_=true;
 ImGui::BeginChild("help_content",{0,-ImGui::GetFrameHeightWithSpacing()-8},false);
 if(dx::modeSpec("WSPR")->available&&ImGui::CollapsingHeader("Additional receive modes",ImGuiTreeNodeFlags_DefaultOpen)){
  ImGui::TextWrapped("%s","FT8, FT4 and WSPR default on and have main-window switches. Saved choices are remembered. Enable other modes in Settings > Reception. Sequence defaults to All and checks every supported length using shared audio; choose one length to reduce work. Match Q65 spacing: All supports A-C; choose a longer single period for D/E. Each period needs a complete UTC interval, up to 30 minutes after its next boundary. The progress bar follows the shortest selected period. Retuning or stopping discards all partial audio. Additional decoders have a separate worker, at most four capture channels and 96 MiB of capture audio. The queue is limited to 32 jobs and 96 MiB of unique audio. Expired or excess jobs are counted as skipped. Q65 decodes individual sequences without cross-sequence averaging.");ImGui::Spacing();
  ImGui::TextWrapped("%s","FT8/FT4 keep circles. WSPR uses squares, FST4 triangles, FST4W diamonds and Q65 hexagons. Color still represents receiver SNR when SNR coloring is enabled. Shared mode and Beacon filters apply to every view. Beacon messages have a sender and may contain its grid and reported transmitter power, but no QSO target or communication arc. Details distinguish transmitter power in dBm/watts from the SNR measured at your receiver. Distances always use your home grid. GridTracker forwarding currently covers FT8/FT4.");
 }
 if(dx::modeSpec("JS8")->available&&ImGui::CollapsingHeader("JS8 reception")){
  ImGui::TextWrapped("%s","Enable JS8 in Modes... or Settings > Reception. It starts off and remembers your choice. Speed: All receives Normal (15 s), Fast (10 s), Turbo / JS8 40 (6 s) and Slow (30 s). Experimental JS8 60 is excluded. Map markers are octagons; SNR keeps the same color scale. Heartbeats use Beacon; directed station messages use Two-way; group messages use Other. This plugin only receives.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Longer text arrives over multiple frames. Incomplete marks a missing final frame or required checksum. Missing or ambiguous headers remain unattributed fragments; message prose never establishes a sender or grid. Details retain raw frames and show speed/completeness. JS8 has a separate worker, a 16-job / 16 MiB queue and a 20-second watchdog. Retuning or stopping discards assembly context. GridTracker forwarding stays FT8/FT4 only.");
 }
 if(ImGui::CollapsingHeader("Window, tabs and waterfall corner",ImGuiTreeNodeFlags_DefaultOpen)){
  ImGui::TextWrapped("%s","Click a station row or use Up/Down in its table to select and highlight the station on the map. Double-click a table row or click a map station to open details. Closing details keeps the selection.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Closing this window hides the interface. Reception and logging continue while the sidebar switch is enabled, the SDR is running and reception is not paused. Open brings the window forward with current data and keeps its size and position. Closing does not reset your data.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Unique stations shows the latest matching reception per sender. All messages includes every retained repeat, newest first, and adds date/time and source columns. Countries heard counts distinct senders and averages their latest matching receptions once. Missing distances are excluded; average SNR is an arithmetic mean in dB, not combined signal power. Each table remembers its layout and sort; filters are shared. Exports follow the active tab.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Corner notifications on waterfall starts on in General settings. Each new reception appears with its flag, country, sender, distance, receiver SNR and full italic message, including repeats. Rows glow for two seconds and expire after an adjustable 10 seconds. The farthest reception stays below with a trophy and flag; only Farthest is gold. Country text is green, sender blue and distance orange. Saved history does not replay old notifications. Long lists/messages scroll. Unmapped regions use a neutral flag.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Country names have flags in every table and in details. Double-click a Countries heard row for all its matching messages, newest first, including repeats. Table filters and time/history scope apply. A horizontal splitter above details adjusts and remembers its height. Details SNR follows the continuous red/yellow/green scale. Details use separate field colors and show sender, target, local date/time, signal, distance, grid, mode, message and source. Distance units in General settings defaults to kilometers; miles is optional and remembered. Displays and distance filters follow the selected unit; logs and exports retain named kilometer fields.");
 }
 if(ImGui::CollapsingHeader("First-heard times",ImGuiTreeNodeFlags_DefaultOpen)){
  ImGui::TextWrapped("%s","One table row per callsign across matching bands and modes. Message, SNR and other reception fields update from the latest matching reception. Equal timestamps use the last arrival. All receptions remain in saved logs and station details.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Msg age shows how long ago the latest reception occurred. A repeated message refreshes that value.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Msg first heard is the first reception of the exact message from the same callsign in this session. Repeats keep that timestamp. A different message has its own first-heard time.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Station first heard is the first reception of any message from that callsign in this session, across all bands and modes.");ImGui::Spacing();
  ImGui::TextWrapped("%s","All age displays show seconds followed by ago through 600 seconds, then the original date and time in the computer's time zone. Sorting uses the underlying timestamp regardless of the displayed format. Hover always shows the original date and time in the computer's time zone. By default, Brown restart starts both again with new receptions. Use saved history for everything restores the first retained reception times. Click a header to sort by its timestamp.");ImGui::Spacing();
 }
 if(ImGui::CollapsingHeader("Columns and filters",0)){
  ImGui::TextWrapped("%s","Sender is the transmitting callsign. Target is the addressed callsign, or -- for a general call or no target. Mod shows the latest FT8/FT4 mode. Target and Mod initially appear last. Drag headers to reorder columns; drag edges to resize. Right-click a header to show or hide columns. Order, widths, visibility and sorting are saved across restarts.");ImGui::Spacing();
  ImGui::TextWrapped("%s","The shared filter bar applies time, band, mode, message type, search and advanced filters to the map and every table tab. It wraps only when needed. All clears the time limit; Reset clears all reception filters. Filters cover all columns. Text, band and mode filters select matching receptions first. Column value ranges then test the displayed rows: SNR, distance, dial MHz, audio Hz, signed DT, bearing, reception count and the three ages. Ages use seconds ago and refresh with time. Limits are inclusive; unknown values do not match enabled limits. A range never replaces the latest row with an older decode.");ImGui::Spacing();
 }
 if(ImGui::CollapsingHeader("Distances and bearing",ImGuiTreeNodeFlags_DefaultOpen)){
  ImGui::TextWrapped("%s","Bracketed numbers are unresolved callsign hashes. Sender and target hashes are compared with resolved sender callsigns recorded in the preceding twelve minutes. A single distinct match supplies the identity; missing or ambiguous matches stay unresolved. Future receptions are excluded. Hash collisions are possible, so a unique match is evidence rather than proof.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Distances use the configured home grid center and the received station grid center. Changing home recalculates saved distances in the background. Map hover shows the grid and coordinates used.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Distances are approximate great-circle distances from Brown's home Maidenhead grid center to the station's received grid center. A four-character grid covers an area, so its center is not an exact transmitter location.");ImGui::Spacing();
  ImGui::TextWrapped("%s","An asterisk marks a cached grid received within the preceding seven days. Repeated messages without a grid do not renew the evidence. Callsign prefixes identify a DXCC entity, not a precise station location.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Approximate unknown distances based on country is in General settings and starts on. [C] marks a near-side six-character grid center inside the matching country outline when no received/cached grid is available. Actual station distance can be much greater. European/Asiatic Russia and Turkey, and East/West Malaysia, use the whole-country outline for estimates only. Original country names stay unchanged. Missing or ambiguous outlines stay unknown. Estimates update existing and new views, sorting and distance filters in the background. They do not become received grids, map positions or distance records. DX activity can use them as a coarse fallback, marked [C]. Raw reception history stays unchanged.");ImGui::Spacing();
  ImGui::TextWrapped("%s","The legacy decoder can report a different distance because it uses a country or regional reference point. Our distances use received grid evidence.");ImGui::Spacing();
  ImGui::TextWrapped("%s","DX ACTIVITY BEARING and the compass follow the shared reception filters, selected time window and session/history scope, without an extra age cutoff. All with saved history includes retained historical and live receptions; Last 15 minutes restricts the sample to those 15 minutes. Older custom ranges use matching past receptions. Current capture bands and alert preferences do not override those filters. All supported modes use received/cached grids first. With country estimates enabled, gridless stations can use the nearest-country grid; [C] marks a bearing containing country estimates. Hover for the sample and estimate count. Country-only direction is coarse because the transmitter may be elsewhere in that country. No matching stations means no eligible station remains under the selected filters and scope. The tooltip identifies the active time filter, history/session scope and sample reception dates. The station count is adjustable. DX activity is the circular mean of geographic short-path bearings to the farthest matching unique stations, measured from home. Historical selections describe past receptions rather than current conditions. It describes heard activity, not measured arrival direction or a propagation forecast. Mixed directions means the bearings are too dispersed for one useful direction.");ImGui::Spacing();
 }
 if(ImGui::CollapsingHeader("Table colors",0)){
  ImGui::TextWrapped("%s","Green country: every displayed station row from one of the three most recently discovered countries. The color stays through message updates. A fourth new country returns the oldest country to normal text. Repeats and other stations from an already heard country do not renew its position. Discovery uses this session, or all retained receptions when saved history is used for everything. Gold bold country and distance mark the farthest station in the selected statistics scope; gold takes precedence over green.");ImGui::Spacing();
  ImGui::TextWrapped("%s","New rows fade through green for nine seconds. Light-green age text marks the newest reception batch until a newer batch arrives.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Teal SNR means at least -10 dB; muted SNR means below -10 dB. This is a display threshold, not a calibrated reception-quality grade. SNR is measured by this receiver. Callsign and grid text remain neutral.");ImGui::Spacing();
 }
 if(ImGui::CollapsingHeader("Map markers and paths",0)){
  ImGui::TextWrapped("%s","The house marks home, the origin for distance and bearing. Turquoise circles mark heard stations; light-green halos mark the latest reception batch. Nearby markers may group at the current zoom.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Color based on SNR starts on and is remembered. When enabled, map circle fills vary continuously from red at -30 dB through yellow at -10 dB to green at +10 dB. A legend shows the range; tooltips show numeric SNR. Selected stations keep gold outlines and newest receptions keep separate halos. Dark-blue curved moving dots connect the transmitter to the station it addresses. General calls create no arc. One arc per station pair, frequency and mode; the latest reply determines its direction. Both endpoints need received grid evidence, which may be cached. An addressed exchange does not prove a completed contact.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Country shading uses your selected color and opacity, initially faint green. Night shading follows the solar day/night boundary. Map filters apply to station markers and exchange arcs.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Station hover shows the latest five distinct messages on that marker's band and mode. The reception label is Age through 600 seconds and Date for older local timestamps. Each message line starts with its latest local date/time, followed by the message in quotes and the receiver SNR measured for that reception. Time and message use separate colors; SNR uses the map color scale. Repeats occupy one row.");ImGui::Spacing();
 }
 if(ImGui::CollapsingHeader("Station actions",0)){
  ImGui::TextWrapped("%s","Right-click a map marker, main table row or details row for callsign lookups and separate Ignore transmitter / Delete transmitter actions. Ignore alone blocks future receptions and keeps saved data. Delete alone removes saved receptions and permits new ones. Each confirmation has one unchecked checkbox to also do the other operation. Unknown identities match their exact identifier; rows without an identity match the exact message. Deletion updates map, tables, saved statistics and known CSV logs, then compacts SQLite in the background. Unignore all permits future receptions; deleted data stays deleted.");ImGui::Spacing();
 }
 if(ImGui::CollapsingHeader("Session and saved history",0)){
  ImGui::TextWrapped("%s","Settings > History > History DB previews and confirms independent one-off deletion by local dates, country, missing distance or missing grid. Keep only selected country also deletes unknown countries. Cached distances are kept unless explicitly included. Current map/table filters do not limit these cleanups. Receptions added after the preview are kept. SQLite and known CSV logs are updated together; interrupted log cleanup retries after restart. Databases are vacuumed with stable reception IDs.");ImGui::Spacing();

  ImGui::TextWrapped("%s","Both saved-history options start off and are saved when changed. Use saved history for stats includes older receptions only in the top statistics. Use saved history for everything also restores map markers, table rows and first-heard times. Shared filters and the time window still apply. All clears the time filter within the selected history/session scope. Calculations run in the background; uptime remains this session's active decoding time. When either history option is on, the amber clock value in parentheses shows elapsed time from the oldest retained reception to now. It includes gaps and stopped periods, uses the full retained database regardless of display filters, and changes when older records are deleted. Hover over UPTIME for its local start date and explanation.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Settings > History limits the database to 100,000 receptions by default. Checked every 30 minutes and at startup. Above the limit, older records are deleted in small background batches until 95,000 remain, while later arrivals are kept. The limit can be changed or disabled. Saved statistics describe retained history. History shows the actual retained start date and automatic deletion count. CSV logs use a separate size limit and are not deleted by this automatic database cleanup.");ImGui::Spacing();
  ImGui::TextWrapped("%s","By default, counters start fresh when Brown starts or the plugin is re-enabled. Saved-history options include retained reception records when enabled. Recent stations always counts only the last five minutes. Uptime counts active decoding time in this session.");ImGui::Spacing();
  ImGui::TextWrapped("%s","Brown starts with a clear table and map unless Use saved history for everything is enabled. Clear keeps saved records. Reset stats turns off both saved-history options and starts a fresh session count. Clearing without resetting stats hides older entries only in the selected views. Turn saved history for everything off and on to restore them.");ImGui::Spacing();
 }
 ImGui::EndChild();ImGui::Separator();
 if(ImGui::Button("Close"))ImGui::CloseCurrentPopup();
 ImGui::EndPopup();
}
